"""精确学习层: 拼音掩码 → (intent, arg) | MISS

定位(相对 voice_agent 现状):
  - voice_agent 已有: 规则直通(parse, 0ms) + 闭集 resolve + phon_match 近似打分 + dry-run
  - 本层只补"规则判 unknown 之后"的精确学习表:
      同一个转写/同音变体再来 → 0 模型、直接给出 intent+arg
      影子模式只记录不接管; live 模式只接管 additive 条目(从 unknown 学习的), 不改变已知命令行为
  - 破坏性意图(close_app/dsh_run/dsh_new/clear_input/dictation_*) 默认拦截, 需 OPENCODE_FASTPATH_DESTRUCTIVE=1
"""
from __future__ import annotations

import json
import os
import time
from pathlib import Path

from .pinyin import Encoder
from .store import MatchStore

HERE = Path(__file__).resolve().parent
DEFAULT_TABLE = HERE / "table.json"
LOG_DIR = HERE / "logs"

DESTRUCTIVE_INTENTS = {"close_app", "dsh_run", "dsh_new", "clear_input", "dictation_on", "dictation_off"}
# 前缀/子串最少字数: 3=通用(默认); 两字命令域(AoE4) 用 fastpath_min_prefix=2 或 env OPENCODE_MIN_PREFIX=2
MIN_PREFIX = int(os.environ.get("OPENCODE_MIN_PREFIX", "3"))


def _norm(text: str) -> str:
    return (text or "").strip().strip("。！？.!?,，、;：\"'“”‘’ ")


class FastPath:
    def __init__(self, table_path=None, mode=None, budget_bytes=64 * 1024 * 1024, log_dir=None):
        self.table_path = Path(table_path or os.environ.get("OPENCODE_FASTPATH_TABLE") or DEFAULT_TABLE)
        self.mode = mode or os.environ.get("OPENCODE_FASTPATH", "off")
        self.budget_bytes = budget_bytes
        self.log_dir = Path(log_dir) if log_dir else LOG_DIR
        self.entries: list[dict] = []
        self.min_prefix = int(MIN_PREFIX)   # 可按域覆盖(hook 读 fastpath_min_prefix)
        self.enc = Encoder()
        self._load()
        self.store = self._make_store()
        self._rebuild()

    def _make_store(self):
        """按条目数自适应容量(上限仍受 budget 约束)"""
        est = sum(len(e.get("triggers") or []) * 2 for e in self.entries) + 64
        need = max(4096, est * 3)
        cap = 1
        while cap < need:
            cap <<= 1
        while cap * 20 > self.budget_bytes and cap > 4096:
            cap >>= 1
        return MatchStore(cap * 20)

    # ---------- 持久化 ----------
    def _load(self):
        if not self.table_path.exists():
            return
        try:
            data = json.loads(self.table_path.read_text(encoding="utf-8"))
            self.entries = data.get("entries", [])
            self.enc = Encoder(data.get("ids", {}))
        except Exception:
            self.entries, self.enc = [], Encoder()

    def _persist(self):
        self.table_path.parent.mkdir(parents=True, exist_ok=True)
        data = {
            "generator": "opencode",
            "session": os.environ.get("OPENCODE_SESSION_ID", "ses_eb3637506ffeoeQ5UIVdyl40q4"),
            "version": 1,
            "ids": self.enc.ids,
            "entries": self.entries,
        }
        self.table_path.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")

    def _rebuild(self):
        self.store = self._make_store()
        for idx, e in enumerate(self.entries):
            for t in e["triggers"]:
                k = self.enc.mask(t)
                if k is None:
                    continue
                if self.store.get2(k) is None:
                    self.store.set(k, idx + 1, 1)
        # 前缀行
        for idx, e in enumerate(self.entries):
            if e.get("destructive"):
                continue
            for t in e["triggers"]:
                for j in range(self.min_prefix, len(t)):
                    pk = self.enc.mask(t[:j])
                    if pk is None:
                        continue
                    cur = self.store.get2(pk)
                    if cur is None:
                        self.store.set(pk, idx + 1, 2)
                    elif cur["action"] != idx + 1 and cur["kind"] == 2:
                        self.store.delete(pk)

    # ---------- 入库 ----------
    def install(self, intent, arg, triggers, additive=True, markers=None):
        triggers = [_norm(t) for t in triggers if _norm(t)]
        # 预分配音节 id(并持久化)
        for t in triggers:
            if self.enc.mask(t, assign=True) is None:  # assign=True 时不会返回 None
                pass
        entry = {
            "intent": intent, "arg": arg, "triggers": triggers,
            "additive": bool(additive),
            "destructive": intent in DESTRUCTIVE_INTENTS,
            "markers": markers or {},
        }
        self.entries.append(entry)
        self._rebuild()
        self._persist()
        return {"id": len(self.entries) - 1, "intent": intent, "arg": arg,
                "triggers": triggers, "destructive": entry["destructive"]}

    # ---------- 路由 ----------
    def route_prefix(self, text, tail_only=False):
        """★ 子串匹配（2026-10-19 用户拍板：核心算法）—— 前后缀不影响命中

        旧实现（tail_only=True）只试"结束在句尾"的子串：
            「打开炉石传说」✓  「帮我打开炉石传说」✓  「打开炉石传说吧」✗（尾字破坏对齐）
        新实现【全子串扫描】：对每个起点 s，向右逐字增量 OR 掩码，长度 ≥ min_prefix
        就查一次表 —— 命令出现在句子的任何位置都能命中。

        排序（决定"撞车"时谁赢）：
          1) 整句行 kind=1 永远优先于前缀行 kind=2
             （前缀行只给逐字早火用；整句路由见到 kind=2 仍按假命中护栏拒绝）
          2) 同类里【跨度最长】优先（"打开厨房灯" > "打开厨房" 前缀）
          3) 长度相同 → 起点更靠前优先；tail_only=True 时再偏好"结束在句尾"

        复杂度：O(n²) 次位运算 + O(n²) 次哈希查表（n≈10~20 → 几十微秒），
        比每个子串重新跑 pypinyin 的 O(n³) 快一个量级。

        tail_only 参数保留只为兼容旧调用；它【不再限制匹配范围】，只参与同分排序。
        """
        t0 = time.perf_counter()
        t = _norm(text)
        n = len(t)
        miss = {"text": t, "key": None, "decision": "miss", "intent": None, "arg": None,
                "additive": False, "blocked": False, "fire_at": None, "start": None,
                "span": None, "kind": 0, "early": False, "latency_us": 0.0}
        if n < self.min_prefix:
            return miss

        # best[kind] = (score, store_row, s, j)
        best = {1: None, 2: None}
        for s in range(0, n - self.min_prefix + 1):
            k = 0
            span_ok = True                      # 子串里一旦出现"未登记音节"→ 本起点后续全废
            for j in range(s, n):
                b = self.enc.char_bit(t[j])
                if b is None:
                    span_ok = False
                else:
                    k |= b
                L = j - s + 1
                if not span_ok or L < self.min_prefix:
                    continue
                # ⚠️ 两字说法（关闭/关掉/退出/结束/停掉…）天生歧义：纯子串会让
                #    「我觉得应该关闭它」触发 close_app。规则：
                #      · 在句首（s==0）→ 允许（"关闭"/"关掉吧"）
                #      · 不在句首时，后面必须只剩语气词（吧/啊/呀/了/…）→ 允许
                #        （"把浏览器关掉吧" ✓）；后面还有名词/代词 → 拒绝
                #        （"我觉得应该关闭它" ✗）
                #    三字及以上仍完全不受前后缀影响。
                if L < 3:
                    _head_ok = (s == 0)
                    _tail_ok = all(c in "吧啊呀哦嘛呢了呗哈" for c in t[j + 1:])
                    if not (_head_ok or _tail_ok):
                        continue
                got = self.store.get2(k)
                if not got:
                    continue
                kind = int(got["kind"])
                if kind not in (1, 2):
                    continue
                score = (L, -s, 1 if (tail_only and j == n - 1) else 0)
                cur = best.get(kind)
                if cur is None or score > cur[0]:
                    best[kind] = (score, got, s, j, k)

        pick = best[1] or best[2]            # ★ 整句行优先（前缀行绝不遮蔽整句）
        if pick is None:
            return miss
        _, got, s, j, k = pick
        aid = got["action"]
        if not (0 < aid <= len(self.entries)):
            return miss
        e = self.entries[aid - 1]
        blocked = bool(e["destructive"]) and os.environ.get("OPENCODE_FASTPATH_DESTRUCTIVE") != "1"
        return {"text": t, "key": hex(k), "decision": "hit", "intent": e["intent"],
                "arg": e["arg"], "additive": e["additive"], "blocked": blocked,
                "fire_at": j + 1, "start": s, "span": t[s:j + 1],
                "kind": int(got["kind"]), "early": int(got["kind"]) == 2,
                "entry": aid - 1,
                "latency_us": round((time.perf_counter() - t0) * 1e6, 1)}

    def route(self, text):
        t0 = time.perf_counter()
        t = _norm(text)
        key = self.enc.mask(t)
        rec = {"text": t, "key": None if key is None else hex(key),
               "decision": "miss", "intent": None, "arg": None,
               "additive": False, "blocked": False,
               "latency_us": 0.0}
        if key is None:
            rec["reason"] = "unknown_syllable"
        else:
            aid = self.store.get(key)
            if aid != -1 and 0 < aid <= len(self.entries):
                e = self.entries[aid - 1]
                blocked = bool(e["destructive"]) and os.environ.get("OPENCODE_FASTPATH_DESTRUCTIVE") != "1"
                rec.update({"decision": "hit", "intent": e["intent"], "arg": e["arg"],
                            "additive": e["additive"], "blocked": blocked,
                            "entry": aid - 1})
        rec["latency_us"] = round((time.perf_counter() - t0) * 1e6, 1)
        return rec

    # ---------- 遥测 ----------
    def observe(self, text, model_result, fr=None):
        fr = fr or self.route(text)
        mi = (model_result or {}).get("intent")
        rec = {
            "ts": time.time(), "session": os.environ.get("OPENCODE_SESSION_ID", ""),
            "mode": self.mode, "text": _norm(text), "key": fr.get("key"),
            "fp": fr.get("decision"), "fp_intent": fr.get("intent"), "fp_arg": fr.get("arg"),
            "model_intent": mi, "model_conf": (model_result or {}).get("conf"),
            "model_src": (model_result or {}).get("src"),
            "rescue": bool(fr.get("decision") == "hit" and mi == "unknown"),
            "fp_latency_us": fr.get("latency_us"),
        }
        self._log("decisions", rec)
        if fr.get("decision") == "hit" and mi == "unknown":
            self._log("rescue", rec)
        if fr.get("decision") == "miss" and mi == "unknown":
            self._log("pending", {"ts": rec["ts"], "text": rec["text"], "reason": fr.get("reason"),
                                  "hint": "规则与快路径都未命中 → 教师候选(LLM 产出产物后可 learn)"})
        return rec

    def _log(self, name, rec):
        self.log_dir.mkdir(parents=True, exist_ok=True)
        p = self.log_dir / f"{name}-{time.strftime('%Y%m%d')}.jsonl"
        with p.open("a", encoding="utf-8") as f:
            f.write(json.dumps(rec, ensure_ascii=False) + "\n")

    # ---------- 报表 ----------
    def stats(self):
        st = self.store.stats()
        return {"mode": self.mode, "entries": len(self.entries), **st}
